    modeButton.addEventListener('click',()=>setMode(state.mode === 'board'?'list':'board'));
    search.addEventListener('input',()=>{state.query=search.value;setMode('list');});
    sorting.addEventListener('change',()=>{state.sort=sorting.value;setMode('list');});
    groupSelect.addEventListener('change',()=>{state.group=groupSelect.value;syncGroup();renderList();});
    reset.addEventListener('click',()=>{state.query='';state.sort='original';state.group='all';state.favoritesOnly=false;search.value='';sorting.value='original';syncGroup();renderList();});
