      const actions=make('div','sc-list-actions'), label=make('label'), pick=make('input');pick.type='checkbox';
      pick.checked=state.cart.has(m.id);pick.setAttribute('aria-label',productName(m)+' · '+t('선택'));
      label.append(pick,make('span','', '선택'));
