      pick.addEventListener('change',()=>{if(pick.checked)setQuantity(m.id,Number(qty.value));else removeItem(m.id);});
      qty.addEventListener('change',()=>{m.qty.value=qty.value;if(state.cart.has(m.id))setQuantity(m.id,Number(qty.value));});
