      m.qty.addEventListener('change',()=>{if(m.pick.checked)setQuantity(m.id,Number(m.qty.value));});
      const edit=make('div','sc-cart-edit'), qty=qtySelect(1,m.name+' 주문 수량'), remove=btn('삭제');
      qty.addEventListener('change',()=>setQuantity(m.id,Number(qty.value)));
      remove.addEventListener('click',()=>removeItem(m.id));
