        return fail('실제 개인정보 보호를 위해 가상 정보 자동 입력 버튼을 사용해 주세요.',$('#customer-name'));
      state.completed={items:[...state.cart].map(([id,n])=>({id,n,unit:unitPrice(id),options:customOptions.get(id)})),...totals(),payment:state.payment};
      state.completed.reward=earnMember(state.completed.discount);
      renderCompletion();
