    summary.append(make('p','',t('상품 금액')+': '+money(c.subtotal)),make('p','',t('쿠폰 할인')+': '+money(c.discount)),make('p','',t('배달비')+': '+money(c.shipping)),
      make('p','',t('총 결제금액')+': '+money(c.total)+' · '+t(c.payment==='card'?'카드':'현금')+' ('+t('가상')+')'),make('p','',t(c.reward?'스탬프 5개 달성 · 쿠폰 1장 지급':'스탬프 1개 적립 완료')));
