  // P08/P10: all date rules are in Korea Standard Time, regardless of visitor locale.
  function kstParts(date=new Date()){
    const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);
    const p=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]));
    const ordinal=Math.floor(Date.UTC(p.year,p.month-1,p.day)/86400000);
    return {...p,ordinal,weekday:new Date(ordinal*86400000).getUTCDay(),key:[p.year,String(p.month).padStart(2,'0'),String(p.day).padStart(2,'0')].join('-')};
  }
  function openingStatus(date=new Date()){
    const p=kstParts(date);
    return p.weekday===1?'정기 휴무 (예시)':p.hour<9?'영업 전 (예시)':p.hour>=21?'영업 종료 (예시)':'영업 중 (예시)';
  }
  function refreshHours(date=new Date()){
    if(!hoursBox)return;
    const key=openingStatus(date),p=kstParts(date);
    const badge=$('.sc-hours-badge',hoursBox);if(badge.textContent!==t(key))badge.textContent=t(key);badge.dataset.open=String(key==='영업 중 (예시)');
    const clock=$('.sc-hours-time',hoursBox),time=p.key+' '+String(p.hour).padStart(2,'0')+':'+String(p.minute).padStart(2,'0')+' KST';
    if(clock.textContent!==time)clock.textContent=time;
  }
  function setupHours(){
    hoursBox=make('div','sc-open-status');
    const badge=make('strong','sc-hours-badge');badge.setAttribute('aria-live','polite');
    hoursBox.append(make('h3','','영업시간 안내 (예시)'),badge,make('span','sc-hours-time'),make('p','','화~일 09:00–21:00 · 월요일 휴무 · 한국 시간'),make('small','','실제 매장이 아니며 가상 주문은 시간과 무관하게 체험할 수 있습니다.'));
    $('#visit .visit-grid dl').after(hoursBox);refreshHours();
  }
  // P09: only IDs, never order information, persist locally.
