  const resDate=()=>$('#sc-res-date'),resTime=()=>$('#sc-res-time');
  function dayKey(n){return new Date(n*86400000).toISOString().slice(0,10);}
  function reservationCheck(key,time,now=new Date()){
    const p=kstParts(now);
    if(!/^\d{4}-\d{2}-\d{2}$/.test(key))return '방문 날짜를 선택해 주세요.';
    const ordinal=Date.parse(key+'T00:00:00Z')/86400000;
    if(!Number.isFinite(ordinal)||dayKey(ordinal)!==key||ordinal<p.ordinal||ordinal>p.ordinal+90)return '오늘부터 90일 이내 날짜를 선택해 주세요.';
    if(new Date(ordinal*86400000).getUTCDay()===1)return '월요일은 휴무입니다.';
    if(!/^\d{2}:(00|30)$/.test(time))return '이용 가능한 시간을 선택해 주세요.';
    const [h,m]=time.split(':').map(Number);const mins=h*60+m;
    if(mins<540||mins>=1260||(ordinal===p.ordinal&&mins<=p.hour*60+p.minute))return '이용 가능한 시간을 선택해 주세요.';
    return '';
  }
  function serviceMessage(id,key='',error=false,detail=''){
    const el=$('#'+id);el.dataset.message=key;el.dataset.detail=detail;el.dataset.error=String(error);
    el.textContent=key?t(key)+(detail?'\n'+detail:''):'';
  }
  function refreshReservation(){
    const p=kstParts();resDate().min=p.key;resDate().max=dayKey(p.ordinal+90);
    const chosen=resTime().value,validDate=resDate().value;
    const first=option('','시간 선택');resTime().replaceChildren(first);
    for(let m=540;m<1260;m+=30){
      const val=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
      if(!reservationCheck(validDate,val))resTime().append(option(val,val));
    }
    if([...resTime().options].some(o=>o.value===chosen))resTime().value=chosen;
  }
  function renderReservation(){
    const form=$('#sc-res-form');$$('input,select,button[type=submit]',form).forEach(el=>el.disabled=!!reservation);
    $('#sc-res-cancel').hidden=!reservation;
    if(reservation){const r=reservation;serviceMessage('sc-res-result','가상 예약 시연 완료',false,r.date+' '+r.time+' KST · '+t(r.people+'명')+' · '+t({none:'지정 없음',window:'창가석',table:'테이블석'}[r.seat])+'\n'+t('실제 예약은 접수되지 않았습니다.'));}
  }
  function setupReservation(){
    refreshReservation();resDate().addEventListener('change',refreshReservation);
    $('#sc-res-form').addEventListener('submit',e=>{
      e.preventDefault();if(reservation)return;
      const date=resDate().value,time=resTime().value,people=Number($('#sc-res-people').value),seat=$('#sc-res-seat').value;
      const problem=reservationCheck(date,time);
      if(problem){serviceMessage('sc-res-result',problem,true);return;}
      if(!Number.isInteger(people)||people<1||people>6||!['none','window','table'].includes(seat))return;
      reservation={date,time,people,seat};renderReservation();
    });
    $('#sc-res-cancel').addEventListener('click',()=>{reservation=null;renderReservation();refreshReservation();serviceMessage('sc-res-result','가상 예약이 취소되었습니다.');resDate().focus();});
  }
